<?php require __DIR__ . '/../includes/config.php';require_admin();if(isset($_GET['download'])){$orders=$pdo->query('SELECT id,customer_name,email,payment_method,total,status,created_at FROM orders ORDER BY created_at DESC')->fetchAll();header('Content-Type: text/csv');header('Content-Disposition: attachment; filename=nexa-orders.csv');$output=fopen('php://output','w');fputcsv($output,['Order','Customer','Email','Payment','Total','Status','Created']);foreach($orders as $order)fputcsv($output,$order);fclose($output);exit;}$stats=['products'=>$pdo->query("SELECT COUNT(*) FROM products")->fetchColumn(),'orders'=>$pdo->query("SELECT COUNT(*) FROM orders")->fetchColumn(),'sales'=>$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status!='cancelled'")->fetchColumn(),'customers'=>$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn()];$recent=$pdo->query('SELECT * FROM orders ORDER BY created_at DESC LIMIT 6')->fetchAll();$pageTitle='Admin dashboard';require __DIR__ . '/../includes/header.php'; ?><div class="admin-shell"><div class="row g-0"><aside class="col-lg-2 admin-side"><div class="eyebrow">Control room</div><h2 class="h4 mt-2">Nexa admin</h2><nav class="mt-4"><a class="active" href="index.php">Overview</a><a href="products.php">Products</a><a href="categories.php">Categories</a><a href="orders.php">Orders</a><a href="users.php">Users</a><a href="../index.php">View store</a><a href="../logout.php">Sign out</a></nav></aside><section class="col-lg-10 p-4 p-lg-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><div class="eyebrow">Store overview</div><h1 class="h2">Good morning, admin.</h1></div><div><a class="btn btn-outline-dark me-2" href="?download=1">Download orders</a><a class="btn btn-accent" href="create_product.php">+ Create product</a></div></div><div class="row g-3 mb-5"><?php foreach([['Products',$stats['products']],['Orders',$stats['orders']],['Revenue','$'.number_format($stats['sales'],2)],['Customers',$stats['customers']]] as [$label,$value]): ?><div class="col-sm-6 col-xl-3"><div class="metric"><div class="tag"><?= $label ?></div><strong><?= $value ?></strong></div></div><?php endforeach; ?></div><div class="panel"><div class="d-flex justify-content-between mb-3"><h2 class="h5 mb-0">Recent orders</h2><a href="orders.php">View all</a></div><div class="table-responsive"><table class="table"><thead><tr><th>#</th><th>Customer</th><th>Date</th><th>Status</th><th class="text-end">Total</th></tr></thead><tbody><?php foreach($recent as $order): ?><tr><td><?= $order['id'] ?></td><td><?= e($order['customer_name']) ?></td><td><?= date('M j, Y',strtotime($order['created_at'])) ?></td><td><?= e($order['status']) ?></td><td class="text-end">$<?= number_format($order['total'],2) ?></td></tr><?php endforeach; ?></tbody></table></div></div></section></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>